seed 20 0 0
hand builder build "#21"; hand builder build "#11"; hand builder build "#12"; hand builder fix "#31"; hand builder ci-red "#33"; hand builder merge-up "#32"
hand reviewer recheck "#41"; hand reviewer validate "#42"; hand reviewer review "#43"
dec builder wide; echo "builder: $(last)"
eq "$(last)" "hold:r#41:c2:- admit:b#32:c3:- hold:r#42:c4:- admit:b#31:c6:- admit:b#33:c6:- admit:b#12:c7:- admit:b#11:c7:- defer:b#21:c8:cap"
eq "$(res)" "b#11 b#12 b#31 b#32 b#33"
cp $S/schedule/reservations.json $S/res.want
for i in 1 2; do dec builder wide; echo "builder again: $(last)"; eq "$(last)" "hold:r#41:c2:- admit:b#32:c3:reserved hold:r#42:c4:- admit:b#31:c6:reserved admit:b#33:c6:reserved admit:b#12:c7:reserved admit:b#11:c7:reserved"; cmp $S/schedule/reservations.json $S/res.want || exit 1; done
dec reviewer wide; echo "reviewer: $(last)"
eq "$(last)" "admit:r#41:c2:- admit:r#42:c4:- defer:r#43:c5:cap"
eq "$(res)" "b#11 b#12 b#31 b#32 b#33 r#41 r#42"
clear; eq "$(res)" ""

