dj() { python3 -c "import json,sys; d=json.load(open(sys.argv[1])); print(' '.join(['T=%s' % d['target']] + ['%s:%s%s:%s' % (k, a['pool'][0], a['ref'], '+'.join(a['reasons']) or '-') for k in ('admit', 'holds', 'deferred') for a in d[k]] + ['held:%s%s' % (h['pool'][0], h['ref']) for h in d['held']]))" $S/d.json; }
last() { python3 -c "import glob,json,sys; L=[json.loads(l) for f in sorted(glob.glob(sys.argv[1] + '/schedule/decisions-*.jsonl')) for l in open(f)]; i=max(j for j, l in enumerate(L) if l['action'] == 'snapshot'); print(' '.join('%s:%s%s:c%s:%s' % (l['action'], l['pool'][0], l['ref'], l['class'], '+'.join(l['reasons']) or '-') for l in L[i + 1:]))" $S; }
seed() { mkdir -p $S/schedule && python3 -c "import json,sys,time; t,age,n=map(int,sys.argv[2:5]); s=lambda x: time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime(time.time()-x)); json.dump(dict(target=t,changed=s(age),starts=[s(1)]*n),open(sys.argv[1],'w'))" $S/schedule/target.json $1 ${2:-0} ${3:-0}; }
age() { python3 -c "import json,sys,time; p=sys.argv[1]; d=json.load(open(p)); d['changed']=time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime(time.time()-200)); json.dump(d,open(p,'w'))" $S/schedule/target.json; }
tgt() { python3 -c "import json,sys; print(json.load(open(sys.argv[1]))['target'])" $S/schedule/target.json; }
res() { python3 -c "import json,sys; print(' '.join(sorted(r['pool'][0]+r['ref'] for r in json.load(open(sys.argv[1])))))" $S/schedule/reservations.json; }
hand() { $C lead handoff $1 $2 "$3" --wait-ack 5 $P >/dev/null || exit 1; }
ids() { python3 -c "import json,sys; [print(json.loads(l)['id']) for l in open(sys.argv[1]) if l.strip()]" $S/inbox/$1.jsonl 2>/dev/null; }
clear() { for l in builder-lead reviewer-lead; do for i in $(ids $l); do grep -qx "done: $i" $S/status/$l.status 2>/dev/null || echo "done: $i" >> $S/status/$l.status; done; done; for p in builder reviewer; do $C schedule release --pool $p $(python3 -c "import json,sys; print(' '.join(r['ref'] for r in json.load(open(sys.argv[1])) if r['pool'] == sys.argv[2]))" $S/schedule/reservations.json $p) $P >/dev/null; done; }
win() { tmux list-windows -t "=$T" -F "#{window_name}" | grep -cx "$1"; }
